css:
@font-face {
  font-family: 'Certificate';
  src: url("/assets/lms/css/certificate.ttf");
  font-weight: 700;
}

.c-top{
    margin-top: -30px;
    margin-left: -45px;
    margin-right: -43px;
}

.c-body{
    margin-top:-63px
}

.c-bottom{
    margin-top: 53px;
}

.subtitle-text {
    font-family: 'Cairo', sans-serif;
    font-style: italic;
    font-size: 18px;
    color: black;
}

.certificate-format {
    border-radius: 8px;
    max-width: 11in;
    max-height: 8.5in;
    color: var(--gray-900);
    margin: 0.5rem;
}

.certificate-title {
    margin-top: -1in;
    position: relative;
    top: -50px;
}

.certificate-text {
    font-family: 'Cairo', sans-serif;
    font-weight: bold;
    color: black;
}



.certified-text {
    font-family: 'Readex Pro', sans-serif;
    font-size: 1.2rem;
    color: black;
}

.inner-border {
    background: url(/assets/lms/images/Certifactes1fm-bg.png);
    background-repeat: round;
    background-size: cover;
    max-width: 11in;
    border-radius: 8px;
    text-align: center;
    padding: 6.5rem;
    width: 11in;

}

.certificate-name {
    font-family: 'Readex Pro', sans-serif;
    font-size: 2.5rem;
    font-style: italic;
    color: black;
}

.certificate-right-align{
    display: flex;
    justify-content: end;
    text-align: left;
}

.onefm-font{
    font-family: 'Readex Pro', sans-serif;
    font-size: 16px;
}

.certificate-footer {
    margin: 2rem auto 0;
    width: 100%;
    padding: 0;
    position: relative;
    top: 49px;
}

.certificate-footer-item {
    color: #192734;
}

.cursive-font {
    font-family: cursive;
    font-weight: 600;
}

.certificate-divider {
    margin: 0.5rem 0px;
    border-top: 1px solid;
}


.training-details {
     font-family: 'Readex Pro', sans-serif;
    font-size: 1.2rem;
}

.certificate-no {
    font-family: Arial, sans-serif;
}
.d-flex {
    margin-top: 60px; /* Adjust as needed */
}

#certificate_format .row:not(.section-break) {
    margin-top: 0px !important;
}

/* Curved text transformations */
span {
    display: inline-block;
}

.C1 { transform: translate(25px, -2px) rotate(-17deg); }
.e1 { transform: translate(20px, -13px) rotate(-17deg); }
.r  { transform: translate(18px, -18px) rotate(-14deg); }
.t1 { transform: translate(15px, -23px) rotate(-13deg); }
.i1 { transform: translate(12px, -27px) rotate(-11deg); }
.f1 { transform: translate(9px, -29px) rotate(-10deg); }
.i2 { transform: translate(5px, -32px) rotate(-7deg); }
.c2 { transform: translate(3px, -34px) rotate(-7deg); }
.a  { transform: translate(1px, -36px) rotate(-1deg); }
.t2 { transform: translate(-2px, -36px) rotate(-1deg); }
.e2 { transform: translate(-4px, -37px) rotate(0deg); }
.o1 { transform: translate(2px, -37px) rotate(0deg); }
.f2 { transform: translate(-2px, -37px) rotate(0deg); }
.C3 { transform: translate(4px, -34px) rotate(3deg); }
.o2 { transform: translate(-2px, -33.64px) rotate(3deg); }
.m  { transform: translate(-4px, -32.31px) rotate(5deg); }
.p  { transform: translate(-6px, -29.98px) rotate(4deg); }
.l  { transform: translate(-10px, -28.65px) rotate(8deg); }
.e3 { transform: translate(-14px, -26.32px) rotate(8deg); }
.t3 { transform: translate(-15px, -21.99px) rotate(10deg); }
.i3 { transform: translate(-18px, -18.66px) rotate(14deg); }
.o3 { transform: translate(-22px, -14.33px) rotate(14deg); }
.n  { transform: translate(-27px, -7px) rotate(20deg); }
